query Query($where: InventoryCountScheduleWhereInput,  $whereCount:InventoryCountWhereInput) {
  schedule:inventoryCountSchedule(where: $where) {
    edges {
      node {
        id
        active
        code
        nextCountAt
        startAt
        facilityId
        frequencyId
        counts:inventoryCounts(where: $whereCount, first: 1, orderBy: {field: scheduledAt, direction:desc}) {
          edges {
            node {
              id
              scheduledAt
              statusId

            }
          }
        }
        anyCount:inventoryCount(first:1){
          edges {
            node {
              id
            }
          }
        }
        dims:dimensions {
          edges {
            node {
              id
              type
              inventoryStatusId
              inventoryTypeId
              locationId
              processId
              productId
              productGroupId
              productStrategyId
              productTypeId
              zoneId
            }
          }
        }
      }
    }
  }
}

data.transform:
function freqs(f, time) {
  const t = $moment(time);
  switch(f) {
    case 'Daily':
      return t.add(1,'day');
    case 'Weekly':
      return t.add(1,'week');
    case 'Monthly':
      return t.add(1,'month');
    case 'Quarterly':
      return t.add(.25,'year');
    case 'Bi Annual':
      return t.add(.5, 'year');
    case 'Annual':
      return t.add(1,'year');
    default:
      throw new Exception(`Frequency ${f} Not Found`);
  }
}


const start = $moment($state.context.REQUEST.DATA.startAt);
const now = $moment();
let next = $moment(start); 

do {
   next = freqs($state.context.REQUEST.DATA.frequency.id, next);
   } while (now.diff(next) > 0)

return {start,next}

