query Query($where: InventoryCountDimensionWhereInput, $orderBy: [InventoryCountDimensionOrderByInput!], $first: Int, $after: String) {
  dim:inventoryCountDimension(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        type
        countId
        inventoryStatusId
        inventoryTypeId
        locationId
        processId
        productId
        productGroupId
        productStrategyId
        productTypeId
