data.transform:
(

$d := dim.edges[$not(node.exclude)].node;
$e := dim.edges[node.exclude].node;
$dg := $groupBy([$d], function ($v) { $v.type });
$dga := $each($dg, function($v, $k) {
(
  $kid :=  $lowerFirst($k) & "Id";
  $count($v) = 1 
  ? {$kid : $lookup($v, $kid)}
  : {
        $kid : {
          "$in": $v.$lookup($, $kid)
      }
    }
)});


$eg := $groupBy([$e], function ($v) { $v.type });
$egn := $each($eg, function($v, $k) {
(
  $kid :=  $lowerFirst($k) & "Id";
  $count($v) = 1 
  ? {$kid : $lookup($v, $kid)}
  : {
        $kid : {
          "$in": $v.$lookup($, $kid)
      }
    }
)});

{
  "$and":[$dga],
  "$nor":[$egn]
}

{
  "$look"
}

)

