query Query($where: InventoryWhereInput, $orderBy: [InventoryOrderByInput!], $first: Int, $after: String) {
  inventory(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        quantity {
          value
          unitId
        }
        inventoryTypeId
        locationId
      }
    }
  }
}

data.transform:
function separateAndReduce(input) {
    const excludeTrue = {};
    const excludeFalse = {};

    input.dim.edges.forEach(edge => {
        const target = edge.node.exclude ? excludeTrue : excludeFalse;
        Object.keys(edge.node).forEach(key => {
            if (edge.node[key] !== null && key !== 'exclude' && key != 'type' && key != 'countId') {
                if (!target[key]) {
                    target[key] = [];
                }
                target[key].push(edge.node[key]);
            }
        });
    });

    return { excludeTrue, excludeFalse };
}

const g = separateAndReduce($);

function handleKeys(obj) {
    let product = {};
    let productStrategy = {};
    let location = {};
    let inventory = {}
    Object.entries(obj).forEach(([key, value]) => {
        switch (key) {
            case "inventoryStatusId":
                inventory = {
                    ...inventory,
                    "inventoryStatusId": {
                        "_in": value
                    }
                }

                break;
            case "inventoryTypeId":
                inventory = {
                    ...inventory,

                    "inventoryTypeId": {
                        "_in": value
                    }

                }
                break;
            case "locationId":
                location = {
                    ...location,

                    "id": {
                        "_in": value
                    }


                }
                break;
            case "productId":
                product = {
                    ...product,

                    "id": {
                        "_in": value
                    }

                }

                break;
            case "productGroupId":
                product = {
                    ...product,

                    "productGroupId": {
                        "_in": value
                    }

                }

                break;
            case "productStrategyId":
                productStrategy = {
                    ...productStrategy,

                    "id": {
                        "_in": value
                    }



                }
                break;
            case "productTypeId":
                product = {
                    ...product,

                    "productTypeId": {
                        "_in": value

                    }
                }

                break;
            case "zoneId":
                location = {
                    ...location,

                    "zoneId": {
                        "_in": value

                    }

                }
                break;
            default:
                { }
        }
    })

    let p = {};
    if (Object.keys(product).length > 0) {
        p = {

            "product": {
                ...product
            }
        }
    }
    let psp = {};
    if (Object.keys(p).length > 0 || Object.keys(productStrategy).length > 0) {
        psp = {
            "productStrategyProcess": {
                "productStrategy": {
                    ...productStrategy,
                    ...p
                }
            }
        }
    }
    let l = {};
    if (Object.keys(location).length > 0) {
        l = {
            "location": {
                ...location
            }
        }
    }

    let result = { ...inventory, ...psp, ...l };





    return result;
}

const w = handleKeys(g.excludeFalse)
const n = handleKeys(g.excludeTrue)
let where = {}
if (Object.keys(w).length > 0) where = w;
if (Object.keys(n).length > 0 ) where["_not"] = n

return w

